  Stage_125663_Desc = {
    Text = "Нетленная клетка, сплетённая руками самих узниц.\nОни плетут вечно. Они никогда не сбегут."
  },
  Stage_125663_Name = {
    Text = "Окукливание"
  },
  Stage_126202_Desc = {
    Text = "Цветы, овации, аплодисменты. Мир вновь возвращается к нему.\nИллюзионист повествования завершил своё представление, и память зрителей рассеивается в изящном поклоне.\nНи одна тайна не покинет руины этой сцены."
  },
  Stage_126202_Name = {
    Text = "Без спойлеров·Четвёртый"
  },
  Stage_126203_Desc = {
    Text = "Встречайте кульминацию истории! Все намёки — лишь топливо, все приготовления — ради того, чтобы зажечь сцену в этот миг."
  },
  Stage_126203_Name = {
    Text = "Пламя·Четвёртое"
  },
  Stage_126204_Desc = {
    Text = "Скука — смертный грех для марионетки."
  },
  Stage_126204_Name = {
    Text = "Поворот, поворот·Четвёртый"
  },
  Stage_126208_Desc = {
    Text = "Занавес поднимается, зрители и аплодисменты исчезли.\nМир пуст, и лишь единственный луч света освещает эту единственную сцену."
  },
  Stage_126208_Name = {
    Text = "Выход на сцену·Шестой"
  },
