  Stage_129163_Name = {
    Text = "Стремительный поезд радости·Обычный"
  },
  Stage_129164_Name = {
    Text = "Стремительный поезд радости · Сложный"
  },
  Stage_129165_Name = {
    Text = "Скорый радостный поезд: безумие"
  },
  Stage_129500_Desc = {
    Text = "Каждый Весенний фестиваль в Древнем царстве Паньлун, независимо от того, где ты находитесь, в каждой семье собираются вместе. \n Они садятся на поезд, идущий в далёкие края, полные надежд и ожиданий момента воссоединения после долгой разлуки."
  },
  Stage_129500_Name = {
    Text = "Поезд желаний"
  },
  Stage_129501_Desc = {
    Text = "Не бойтесь, это всего лишь игра.\nЖестокая и ужасная игра."
  },
  Stage_129501_Name = {
    Text = "Игра началась"
  },
  Stage_129502_Desc = {
    Text = "Не останавливайся, не отступай. \n Если добрые люди опустят оружие, зло воспользуется этим и начнёт Погоня."
  },
  Stage_129502_Name = {
    Text = "Вторая жертва"
  },
  Stage_129503_Desc = {
    Text = "Это абсолютная Контратака справедливости... да?"
  },
  Stage_129503_Name = {
    Text = "Тихое убийство"
  },
  Stage_129504_Desc = {
    Text = "Та ручка часто появляется в твоих снах.\nТолкнуть её или потянуть вниз — это вопрос."
  },
