  Stage_131105_Desc = {
    Text = "Нетленная клетка, сплетённая руками самих узниц.\nОни плетут вечно. Они никогда не сбегут."
  },
  Stage_131105_Name = {
    Text = "Окукливание"
  },
  Stage_132466_Desc = {
    Text = "Только для внутреннего тестирования"
  },
  Stage_132466_Name = {
    Text = "Тестовая среда·Глава забвения"
  },
  Stage_139577_Desc = {
    Text = "Отлично, эти… нет-нет-нет, я хочу сказать — эти чёрные коты просто ужасны!"
  },
  Stage_139577_Name = {
    Text = "Чёрно-золотой прилив"
  },
  Stage_139578_Desc = {
    Text = "Карманы набиты серебряными ядрами и золотыми купонами — победоносный полководец возвращается с богатой добычей."
  },
  Stage_139578_Name = {
    Text = "С полным уловом"
  },
  Stage_139579_Desc = {
    Text = "Ты нацелился на самого большого кота, а он — на тебя."
  },
  Stage_139579_Name = {
    Text = "Исполин"
  },
  Stage_139580_Desc = {
    Text = "Но котов ещё много, давай-ка ещё… последний разочек?"
  },
  Stage_139580_Name = {
    Text = "Еще раз"
  },
  Stage_139581_Desc = {
    Text = "Когда первый серебряный проблеск засиял в чёрном океане, ты замахнулся сетью для ловли котов с удвоенной силой."
  },
  Stage_139581_Name = {
    Text = "Первая партия серебряных ядер"
  },
  Stage_139582_Desc = {
    Text = "Чёрный кот сопротивляется тебе — значит, ты всё делаешь правильно."
  },
  Stage_139582_Name = {
    Text = "Сопротивление поимке"
  },
  Stage_139583_Desc = {
    Text = "Чем больше сеть — тем больше котов. На большого кота нужна большая сеть — тяни!"
  },
  Stage_139583_Name = {
    Text = "Тяни сеть! Тяни!"
  },
  Stage_140299_Desc = {
    Text = "Расцветай, танцуй в полёте.\nТы решила: каким бы тернистым ни был путь, ты никогда не отпустишь её руку.\nВ миг нашего расставания пусть искажённый мир наполнится «истиной»."
  },
  Stage_140299_Name = {
    Text = "Прощание"
  },
  Stage_140300_Desc = {
    Text = "Память подобна семени — она таит в себе всё, но хранит молчание.\nПока полив не заставит её пустить корни и дать ростки, пока земля не примет и не укроет её, позволив черпать силу из реальности."
  },
  Stage_140300_Name = {
    Text = "«Память»"
  },
  Stage_140301_Desc = {
    Text = "Память подобна семени — она таит в себе всё, но хранит молчание.\nПока полив не заставит её пустить корни и дать ростки, пока земля не примет и не укроет её, позволив черпать силу из реальности."
  },
  Stage_140301_Name = {
    Text = "«Память»"
  },
