  Stage_148356_Name = {
    Text = "Стремительный поезд радости·Обычный"
  },
  Stage_148357_Name = {
    Text = "Скорый радостный поезд: безумие"
  },
  Stage_148358_Name = {
    Text = "Стремительный поезд радости · Сложный"
  },
  Stage_148732_Name = {
    Text = "Нарушитель клятвы·Пробный уровень Ожье"
  },
  Stage_20089_Desc = {
    Text = "Она выполнила своё обещание, и наконец вы можете вернуться домой вместе."
  },
  Stage_20089_Name = {
    Text = "Золотая Голова"
  },
  Stage_20090_Desc = {
    Text = "Салон на Западном острове — самое важное художественное событие. \nЗдесь те, кто неизвестен, стремятся к успеху, а те, кто уже достиг славы, стремятся к вечности."
  },
  Stage_20090_Name = {
    Text = "Смерть госпожи Коралл"
  },
  Stage_20091_Desc = {
    Text = "Ответ находится в середине моря."
  },
  Stage_20091_Name = {
    Text = "Посреди моря"
  },
  Stage_20092_Desc = {
    Text = "Эрнст Клаудель когда-то был сеньором Безансона.\nДо тех пор этот род по-прежнему уважаем в регионе."
  },
  Stage_20092_Name = {
    Text = "Как при личной встрече"
  },
  Stage_20426_Desc = {
    Text = "Конец уже предопределён, как ты ни пытайся, как она ни борется, прошлое невозможно изменить."
  },
  Stage_20426_Name = {
    Text = "Великолепный финал"
  },
  Stage_20427_Desc = {
    Text = "Сновидения не длятся вечно, как и прекрасные мелодии не звучат бесконечно."
  },
  Stage_20427_Name = {
    Text = "Музыка стихла, зрители разошлись"
  },
  Stage_20428_Desc = {
    Text = "Король заперт в возвышенном троне.\nМир меняется, но его печаль остается неизменной."
  },
  Stage_20428_Name = {
    Text = "Её страна"
  },
  Stage_20429_Desc = {
    Text = "Она бродила без цели по срезам памяти.\nНичего не зная, ничего не чувствуя, снова и снова.."
  },
  Stage_20429_Name = {
    Text = "Барьер памяти"
  },
  Stage_20430_Desc = {
    Text = "Что находится в конце лабиринта? День, ночь или бесконечное ничто? \n Ей нужно найти Лечение самостоятельно."
  },
  Stage_20430_Name = {
    Text = "Глубина лабиринта"
  },
  Stage_20431_Desc = {
    Text = "Дети, больше детей, непрерывный поток детей...\nОни — её единственная любовь."
  },
  Stage_20431_Name = {
    Text = "Кластер сознания"
  },
  Stage_20432_Desc = {
    Text = "Не надо открывать ту Ворота, которая не принадлежит тебе.."
  },
  Stage_20432_Name = {
    Text = "Ворота"
  },
  Stage_20433_Desc = {
    Text = "Сновидения не длятся вечно, как и прекрасные мелодии не звучат бесконечно."
  },
  Stage_20433_Name = {
    Text = "Музыка стихла, зрители разошлись"
  },
  Stage_20434_Desc = {
    Text = "Эрнст Клаудель когда-то был сеньором Безансона.\nДо тех пор этот род по-прежнему уважаем в регионе."
  },
  Stage_20434_Name = {
    Text = "Как при личной встрече"
  },
  Stage_20435_Desc = {
    Text = "Он уже сделал всё, что мог. Дальше пусть время пишет новую балладу."
  },
  Stage_20435_Name = {
    Text = "Новая песнь"
  },
  Stage_20436_Desc = {
    Text = "Призыв, которое невозможно забыть, или сновидение, которое не покидает мысли?"
  },
  Stage_20436_Name = {
    Text = "Нити прошлого"
  },
  Stage_20437_Desc = {
    Text = "Дети, больше детей, непрерывный поток детей...\nОни — её единственная любовь."
  },
  Stage_20437_Name = {
    Text = "Кластер сознания"
  },
  Stage_20438_Desc = {
    Text = "Сновидения не длятся вечно, как и прекрасные мелодии не звучат бесконечно."
  },
  Stage_20438_Name = {
    Text = "Музыка стихла, зрители разошлись"
  },
  Stage_20439_Desc = {
    Text = "Это ваш секрет, он будет запечатлен в душе и сопровождать вас на веки."
  },
  Stage_20439_Name = {
    Text = "Мечта, или идеал"
  },
  Stage_20440_Desc = {
    Text = "Мир после взрыва погрузился в темноту, ты блуждаешь в мире духов, не зная, что ждёт тебя и Эрику."
  },
  Stage_20440_Name = {
    Text = "Голос произнёс"
  },
  Stage_20441_Desc = {
    Text = "Ещё одно сновидение, ещё одна часть прошлого — на этот раз вы видите Эрику из плоти и крови."
  },
  Stage_20441_Name = {
    Text = "Запуск теста"
  },
  Stage_20442_Desc = {
    Text = "Мир после взрыва погрузился в темноту, ты блуждаешь в мире духов, не зная, что ждёт тебя и Эрику."
  },
  Stage_20442_Name = {
    Text = "Голос произнёс"
  },
  Stage_20443_Desc = {
    Text = "Мир после взрыва погрузился в темноту, ты блуждаешь в мире духов, не зная, что ждёт тебя и Эрику."
  },
  Stage_20443_Name = {
    Text = "Голос произнёс"
  },
  Stage_20444_Desc = {
    Text = "Эрнст Клаудель когда-то был сеньором Безансона.\nДо тех пор этот род по-прежнему уважаем в регионе."
  },
  Stage_20444_Name = {
    Text = "Как при личной встрече"
  },
  Stage_20445_Desc = {
    Text = "Дети, больше детей, непрерывный поток детей...\nОни — её единственная любовь."
  },
  Stage_20445_Name = {
    Text = "Кластер сознания"
  },
  Stage_20697_Desc = {
    Text = "Каждый момент кто-то умирает, так же как и каждый момент кто-то рождается.\nТолько Чёрная Чёрная тень отличается. Она поглощена временем, связана через Связывание этой страдающей землёй.\nЖизнь за жизнью, не умирая, не рождаясь."
  },
  Stage_20697_Name = {
    Text = "Песнь теней"
  },
  Stage_20698_Desc = {
    Text = "Бог сказал, что они должны родиться, чтобы претерпеть страдания и пролить кровь.\nТак же, как солнце должно восходить, а дождь должен падать.\nВсё происходит к лучшему."
  },
  Stage_20698_Name = {
    Text = "Земля Горьких Дождей"
  },
  Stage_20699_Desc = {
    Text = "Мы идём вперёд, чтобы торжественно вернуться.\nМы живём, чтобы умереть достойно."
  },
  Stage_20699_Name = {
    Text = "Издалека"
  },
  Stage_20700_Desc = {
    Text = "Оно единственное живое существо здесь, и всё, что оно видит, подчиняется ему.\n—— Оно является верховным королём."
  },
  Stage_20700_Name = {
    Text = "Королевство зверей"
  },
  Stage_20701_Desc = {
    Text = "Они пересекли границу между жизнью и смертью, встретившись снова у могильной плиты.\nЛица прижаты Близкий Близкий друг к другу, руки сцеплены, а в каждом вздохе чувствуется запах разложения."
  },
  Stage_20701_Name = {
    Text = "Уединённая Воссоединение"
  },
  Stage_20702_Desc = {
    Text = "Мы — существа, собранные из костей и слёз.\nСегодня ночью мы собрались здесь, чтобы увидеть реку, переливающуюся множеством радужных цветов."
  },
  Stage_20702_Name = {
    Text = "Сходка охотников за черепами"
  },
  Stage_20703_Desc = {
    Text = "Когда Чёрная Чёрная тень погружается во тьму, капля воды сливается с дождем.\nВремя охоты скоро настанет.."
  },
  Stage_20703_Name = {
    Text = "Надвигается буря"
  },
  Stage_20704_Desc = {
    Text = "Они пересекли границу между жизнью и смертью, встретившись снова у могильной плиты.\nЛица прижаты Близкий Близкий друг к другу, руки сцеплены, а в каждом вздохе чувствуется запах разложения."
  },
  Stage_20704_Name = {
    Text = "Уединённая Воссоединение"
  },
  Stage_20705_Desc = {
    Text = "Оно единственное живое существо здесь, и всё, что оно видит, подчиняется ему.\n—— Оно является верховным королём."
  },
  Stage_20705_Name = {
    Text = "Королевство зверей"
  },
  Stage_20706_Desc = {
    Text = "Мы идём вперёд, чтобы торжественно вернуться.\nМы живём, чтобы умереть достойно."
  },
  Stage_20706_Name = {
    Text = "Издалека"
  },
  Stage_20707_Desc = {
    Text = "Бог сказал, что они должны родиться, чтобы претерпеть страдания и пролить кровь.\nТак же, как солнце должно восходить, а дождь должен падать.\nВсё происходит к лучшему."
  },
  Stage_20707_Name = {
    Text = "Земля Горьких Дождей"
  },
  Stage_20708_Desc = {
    Text = "Когда Чёрная Чёрная тень погружается во тьму, капля воды сливается с дождем.\nВремя охоты скоро настанет.."
  },
  Stage_20708_Name = {
    Text = "Надвигается буря"
  },
  Stage_20709_Desc = {
    Text = "Мы — существа, собранные из костей и слёз.\nСегодня ночью мы собрались здесь, чтобы увидеть реку, переливающуюся множеством радужных цветов."
  },
  Stage_20709_Name = {
    Text = "Сходка охотников за черепами"
  },
  Stage_20710_Desc = {
    Text = "Каждый момент кто-то умирает, так же как и каждый момент кто-то рождается.\nТолько Чёрная Чёрная тень отличается. Она поглощена временем, связана через Связывание этой страдающей землёй.\nЖизнь за жизнью, не умирая, не рождаясь."
  },
  Stage_20710_Name = {
    Text = "Песнь теней"
  },
  Stage_20711_Desc = {
    Text = "Строго говоря, это не трагедия.\nВ словаре воина нет слова «трагедия»."
  },
  Stage_20711_Name = {
    Text = "Занавес трагедии"
  },
  Stage_20712_Desc = {
    Text = "Салон на Западном острове — самое важное художественное событие. \nЗдесь те, кто неизвестен, стремятся к успеху, а те, кто уже достиг славы, стремятся к вечности."
  },
  Stage_20712_Name = {
    Text = "Смерть госпожи Коралл"
  },
  Stage_20713_Desc = {
    Text = "Что находится в конце лабиринта? День, ночь или бесконечное ничто? \n Ей нужно найти Лечение самостоятельно."
  },
  Stage_20713_Name = {
    Text = "Глубина лабиринта"
  },
  Stage_20714_Desc = {
    Text = "Строго говоря, это не трагедия.\nВ словаре воина нет слова «трагедия»."
  },
  Stage_20714_Name = {
    Text = "Занавес трагедии"
  },
  Stage_20715_Desc = {
    Text = "Что находится в конце лабиринта? День, ночь или бесконечное ничто? \n Ей нужно найти Лечение самостоятельно."
  },
  Stage_20715_Name = {
    Text = "Глубина лабиринта"
  },
  Stage_20716_Desc = {
    Text = "Салон на Западном острове — самое важное художественное событие. \nЗдесь те, кто неизвестен, стремятся к успеху, а те, кто уже достиг славы, стремятся к вечности."
