  Stage_22313_Name = {
    Text = "Открой глаза"
  },
  Stage_23624_Desc = {
    Text = "Некоторые люди рождены для приключений, другие же превращают свою жизнь в красивую любовную историю.\nВ конце концов, каждый человек — режиссер своей собственной жизни."
