  Stage_35099_Desc = {
    Text = "«Шш... Угадай, что я вижу через твои глаза?» \nПосле того как Орета расплакалась от страха перед Хранителем тайн, Ротань чуть не снесла четвёртую стену в комнате Хранителя тайн — настолько тревожным был её плач."
  },
  Stage_35099_Name = {
    Text = "IX·Четвёртая стена в театре"
  },
  Stage_35100_Desc = {
    Text = "«Не надо позволять зрителям полностью погружаться в Сюжет, заставляйте их анализировать и критиковать то, что происходит на сцене.» \n Орета так оценивает эту теорию: Орета не хочет, чтобы её ругали, и хочет стать другом для всех!"
  },
  Stage_35100_Name = {
    Text = "VIII·Эффект отчуждения"
  },
  Stage_35129_Desc = {
    Text = "Она является границей между сновидением и реальностью, отражением глубин души каждого, кто смотрит на ночное небо."
  },
  Stage_35129_Name = {
    Text = "Искажённые звёзды"
  },
  Stage_35129_StageInitStateText = {
    Text = "Морской кошмар"
  },
  Stage_35130_Desc = {
    Text = "Она Готово."
  },
  Stage_35130_Name = {
    Text = "Внутренний огонёк"
  },
  Stage_35571_Desc = {
    Text = "Потому что ты Близкий Близкий друг Ореты, она решила познакомить тебя со всеми своими друзьями."
  },
  Stage_35571_Name = {
    Text = "Грандиозная коллекция друзей"
  },
  Stage_35572_Desc = {
    Text = "Потому что ты Близкий Близкий друг Ореты, она решила познакомить тебя со всеми своими друзьями."
  },
  Stage_35572_Name = {
    Text = "Грандиозная коллекция друзей"
  },
  Stage_35573_Desc = {
    Text = "Потому что ты Близкий Близкий друг Ореты, она решила познакомить тебя со всеми своими друзьями."
  },
  Stage_35573_Name = {
    Text = "Грандиозная коллекция друзей"
  },
  Stage_35574_Desc = {
    Text = "Орета нравишься ей, поэтому она хочет, чтобы ты стал другом и провёл с ней обычный день."
  },
  Stage_35574_Name = {
    Text = "Тихий белый день"
  },
  Stage_35575_Desc = {
    Text = "Поскольку все были рядом с Оретой, она не боялась ни одной точки засыпать."
  },
  Stage_35575_Name = {
    Text = "Дворец под водой"
  },
  Stage_35843_Name = {
    Text = "Пробный Уровень «Леди глубин»"
  },
  Stage_35857_Desc = {
    Text = "Звёзды отправились туда, куда должны были попасть. Они общаются Близкий Близкий друг с другом через трансценденцию, недоступную для человеческого понимания, плетя невидимую сеть. Эта сеть захватывает текучее время и уходящие световые годы."
  },
  Stage_35857_Name = {
    Text = "Неизвестно звёздная орбита"
  },
  Stage_36125_Desc = {
    Text = "Неблагословённый ребёнок поёт гимн в море.\nШшш... Прошу вас, сохраняйте тишину, не будите Его вечный сон."
