  Stage_36614_Desc = {
    Text = "Безудержное блудодейство, Распутство...\n— А дальше?\nПодвергнутся вечному огненному наказанию, в назидание.\n— О."
  },
  Stage_36614_Name = {
    Text = "Вечер смерти, медовой воды и песен"
  },
  Stage_36615_Desc = {
    Text = "Часть 4 брака и четыре похороны — они стали всеми заметками к «жизни чувств» Ванды на земле."
  },
  Stage_36615_Name = {
    Text = "Часть 4 свадьбы"
  },
