  Stage_36619_Name = {
    Text = "Вечер смерти, медовой воды и песен"
  },
  Stage_36620_Desc = {
    Text = "Королева сидит на высоком троне.\nВместе с ней находятся бесконечные сокровища, богатства и небольшая часть затопленных космических руин."
  },
  Stage_36620_Name = {
    Text = "Королева-отступница"
  },
  Stage_36621_Desc = {
    Text = "До бедствия столица была продолжением её амбиций и желания.\nПосле бедствия столица стала темницей мрака и уединения."
  },
  Stage_36621_Name = {
    Text = "Дудочник"
  },
  Stage_36887_Name = {
    Text = "Пробный Уровень Королевы тернов"
  },
  Stage_38756_Desc = {
    Text = "Она закрыла глаза и бесприцельно плавала в пустоте космоса.\nГод, сто лет... Наконец, однажды она сказала себе: «Это неважно. Я сама определю, что истинно, а что ложно». \nКоролева и её бессмертный город — Иссарау, так и остались в бескрайних звёздных реках вселенной.\nОна рассказала мне историю Иссарау, чтобы она была навсегда запечатлена."
  },
  Stage_38756_Name = {
    Text = "Один отрывок памяти·шестая часть воспоминаний"
  },
