  Stage_44219_Name = {
    Text = "Запросить·Рост Пяти"
  },
  Stage_44220_Desc = {
    Text = "О, невежественные люди, вы разожгли пламя и превратили надежду и искупление в Пепел.\nКаков вкус этого самопровозглашённого правосудия, когда вы боретесь в темной смерти?"
  },
  Stage_44220_Name = {
    Text = "Раскаяние·Рост (Первый)"
  },
  Stage_44221_Desc = {
    Text = "Те, что приносят им пользу, являются хорошими, все благословения, которые не касаются их, являются проклятиями.\n«Какое благословение, это явно злобная кровавая магия!»\n«Это определённо колдовство... он демон!»"
  },
  Stage_44221_Name = {
    Text = "Обвинение·Шестое расширение"
  },
  Stage_44222_Desc = {
    Text = "Страх перед болезнью заставляет их сопротивляться.\n«Почему только ему даровано благословение? Я тоже болен!»\n«Я самый тяжёлый случай, я должен быть первым, кто получит благословенный!»"
  },
