  Stage_54558_Name = {
    Text = "Новый король"
  },
  Stage_54804_Desc = {
    Text = "«Я, как рассказчик, и есть Ассасин» — действительно банальный трюк, лишённый красоты и техники.\nК сожалению, на этот раз я всё-таки это заметил."
