  Stage_55167_Name = {
    Text = "Первая роза · первая"
  },
  Stage_55391_Desc = {
    Text = "«Позволь мне обменять первую розу на твоё первое стихотворение.»"
  },
  Stage_55391_Name = {
    Text = "Псалтирь 1843"
  },
  Stage_55392_Desc = {
    Text = "Сад — это загадка, роза — её Лечение."
  },
  Stage_55392_Name = {
    Text = "Оставшийся аромат"
  },
  Stage_55393_Desc = {
    Text = "«Позволь мне обменять первую розу на твоё первое стихотворение.»"
  },
  Stage_55393_Name = {
    Text = "Псалтирь 1843"
  },
  Stage_55394_Desc = {
    Text = "Нет траура, нет и ветра.\nТолько остатки чернил поэта, прощальный звон за сад."
  },
  Stage_55394_Name = {
    Text = "Элегия сада"
  },
  Stage_55395_Desc = {
    Text = "Статуя — это риторика короля, молчание — это риторика статуи."
  },
  Stage_55395_Name = {
    Text = "Реторика статуя"
  },
  Stage_55396_Desc = {
    Text = "Они смотрели Близкий Близкий друг на друга через сад.\nВ саду было бесчисленное множество дорог, принадлежащих каждой из них, каждая из них вела врозь."
  },
  Stage_55396_Name = {
    Text = "Сад раздвоенных тропинок"
  },
  Stage_55397_Desc = {
    Text = "Пусть первые похороны станут прощанием с костями, а вторые — прощанием со временем."
  },
  Stage_55397_Name = {
    Text = "Запоздалые похороны"
  },
  Stage_55398_Desc = {
    Text = "Отличные стихи заставляют человека почувствовать себя частью описываемой сцены.\nКлассическая эстетическая теория объясняет это так."
  },
  Stage_55398_Name = {Text = "Поэт"},
  Stage_55399_Desc = {
    Text = "Цветы Западного острова приглашают вас присоединиться к ним и попасть в этот сон."
  },
  Stage_55399_Name = {
    Text = "Столица цветов"
  },
  Stage_55400_Desc = {
    Text = "Так называемая родина — это не что иное, как лживая Иллюзия."
  },
  Stage_55400_Name = {Text = "Дом"},
  Stage_55401_Desc = {
    Text = "«Позволь мне обменять первую розу на твоё первое стихотворение.»"
  },
  Stage_55401_Name = {
    Text = "Псалтирь 1843"
  },
  Stage_55551_Desc = {
    Text = "Эта снежная гора обладает жизнью, в её ущельях эхом раздаются свистящие звуки, это она зовёт свою дочь.\nПриходи скорее, приходи скорее.\nИдёт ли дочь к матери, или Матушка идёт к дочери?\nНа вершине снежной горы два пустых пространства наконец встретились."
  },
  Stage_55551_Name = {
    Text = "Видеть гору·3"
  },
  Stage_55552_Desc = {
    Text = "Эта снежная гора обладает жизнью, в её ущельях эхом раздаются свистящие звуки, это она зовёт свою дочь.\nПриходи скорее, приходи скорее.\nИдёт ли дочь к матери, или Матушка идёт к дочери?\nНа вершине снежной горы два пустых пространства наконец встретились."
  },
  Stage_55552_Name = {
    Text = "Видеть гору·2"
  },
  Stage_55553_Desc = {
    Text = "Эта снежная гора обладает жизнью, в её ущельях эхом раздаются свистящие звуки, это она зовёт свою дочь.\nПриходи скорее, приходи скорее.\nИдёт ли дочь к матери, или Матушка идёт к дочери?\nНа вершине снежной горы два пустых пространства наконец встретились."
  },
  Stage_55553_Name = {
    Text = "Видеть гору·первая часть"
  },
  Stage_55554_Desc = {
    Text = "Замерзшая почва снежной горы иссохшая и мертвая, уничтожив всякую жизнь.\nНо воля к жизни всегда остается стойкой.\nТолько когда снежная гора растает, холодные капли упадут в почву.\nИ тогда непокорное семя мгновенно прорастет на вершине."
  },
  Stage_55554_Name = {
    Text = "Разгромить почву·Пятый"
  },
