  Stage_55584_Name = {
    Text = "Разрушение Почвы: безумие"
  },
  Stage_55584_StageInitStateText = {
    Text = "Кровотечение"
  },
  Stage_55585_Desc = {
    Text = "Замерзшая почва снежной горы иссохшая и мертвая, уничтожив всякую жизнь.\nНо воля к жизни всегда остается стойкой.\nТолько когда снежная гора растает, холодные капли упадут в почву.\nИ тогда непокорное семя мгновенно прорастет на вершине."
  },
  Stage_55585_Name = {
    Text = "Разгромить почву·Часть 4"
  },
  Stage_56404_Desc = {
    Text = "Морфи узнала, что она не первая Святая дева дева. На протяжении тысячелетий в теле бесчисленных девушек билось подобное сердцебиение.\nВ бесчисленных измерениях времени, бесчисленные сердца перекликались в едином ритме."
  },
  Stage_56404_Name = {
    Text = "Пространственно-временная пропасть·безумие"
  },
  Stage_56404_StageInitStateText = {
    Text = "Морской кошмар"
  },
  Stage_56405_Desc = {
    Text = "Это последнее достоинство всей жизни.\nС глубоким морем в качестве гробницы и небом в качестве одеяла, боги погребены в течении океана."
  },
  Stage_56405_Name = {
    Text = "Покров·безумие"
  },
  Stage_56405_StageInitStateText = {
    Text = "Морской кошмар"
  },
  Stage_56407_Desc = {
    Text = "Он прибыл беззвучно и без сердца.\nЕго сердце продолжает свою жизнь в ее крови без горя."
  },
  Stage_56407_Name = {
    Text = "Его Нисхождение·безумие"
  },
  Stage_56407_StageInitStateText = {
    Text = "Морской кошмар"
  },
  Stage_56408_Desc = {
    Text = "Она считала звёзды в высоте, ожидая момент, которого не ждала.\n«Звёзды сошлись звёзд», когда звёзды поднимаются над морем, она сольётся с россыпью звёзд."
  },
  Stage_56408_Name = {
    Text = "Жёлтая звезда · безумие"
  },
  Stage_56408_StageInitStateText = {
    Text = "Морской кошмар"
  },
  Stage_56409_Desc = {
    Text = "Она не имеет права решать, кому принадлежит эмбрион, вживленный в её грудную клетку.\nОна не имеет права решать, куда бежать, чью руку держать, с кем скитаться и блуждать.\nПеред судьбой, парящей в морской иллюзии, каждый — лишь агнец на заклание."
  },
  Stage_56409_Name = {
    Text = "Жертва невинных·безумие"
  },
  Stage_56409_StageInitStateText = {
    Text = "Морской кошмар"
  },
  Stage_56410_Desc = {
    Text = "Не обязательно использовать гильотину, чтобы казнить её.\nЕё Матушка сама исполнила этот трагический акт."
  },
  Stage_56410_Name = {
    Text = "Палач·безумие"
  },
  Stage_56410_StageInitStateText = {
    Text = "Морской кошмар"
  },
  Stage_56411_Desc = {
    Text = "Тишина. Тишина. Тишина.\nПодо льдом всё вечно, даже дыхание заморожено. Выживание и смерть — это одно и то же, как и состояние покоя и пробуждение не имеют различий.\nУ Элворт никогда не будет её весны."
  },
  Stage_56411_Name = {
    Text = "Затаивание·безумие"
  },
  Stage_56411_StageInitStateText = {
    Text = "Морской кошмар"
  },
