  Stage_58370_StageInitStateText = {Text = "Конец"},
  Stage_58371_Desc = {
    Text = "«У меня ничего не осталось.» Бездомный с односторонней слепотой сказал, «Только этот цветок могу преподнести вам, великая королева.» \nОна приняла белую фрезию, но почувствовала себя озадаченной. Казалось, эта сцена уже бесчисленное количество раз повторялась в её памяти. \nВновь и вновь, словно лабиринт Минотавра."
  },
  Stage_58371_Name = {
    Text = "Фрезия·Часит 6"
  },
  Stage_58372_Desc = {
    Text = "Королева и её бессмертная цитадель — Иссарау.\nО близнецы, благословлённые космосом, вы нежно обвиты пуповиной судьбы.\nОдни говорят, что мудрая королева привела свой народ в Иссарау, как описано в «Откровении».\nДругие же говорят, что русла рек Иссарау бурлили из года в год, пока не породили королеву."
  },
  Stage_58372_Name = {
    Text = "Откровение·Часть третья"
  },
  Stage_58373_Desc = {
