  Stage_59077_Name = {
    Text = "Первородный разлом II"
  },
  Stage_59502_Desc = {
    Text = "Перед лицом вашего исходного отчаяния. Перед лицом вашего исходного страха.\nВстаньте рядом, хоть вас и не видно, и победите Его."
  },
  Stage_59502_Name = {
    Text = "Решающая битва: Изначальная Чёрная Чёрная Чёрная Чёрная тень"
  },
  Stage_59503_Desc = {
    Text = "Поминай – это твоя клятва,забвение – это твое Жертвенный ритуал."
  },
  Stage_59503_Name = {
    Text = "Жертвоприношение"
  },
  Stage_59503_StageInitStateText = {
    Text = "Исходный"
  },
  Stage_59504_Desc = {
    Text = "Стоя в храме сновидений, поддерживай руины.\nЗащита пылинки под тобой, несущей все твои заботы и привязанности."
  },
  Stage_59504_Name = {
    Text = "Разрушение сна"
  },
