  Stage_62348_Desc = {
    Text = "Это кульминация звёзд. Это финал вселенной.\nВ этой тишине внимательно Прислушайся — \nСлышите эту ноту?"
  },
  Stage_62348_Name = {Text = "Финал"},
  Stage_66016_Desc = {
    Text = "Он есть высшая воля, создатель вселенной, завершитель всего сущего.\nПлачьте перед Ним. За вашу слабую храбрость, за Его бесконечную Независимый."
  },
  Stage_66016_Name = {
    Text = "Работный дом: взгляд скорби"
  },
