  Stage_66018_Name = {
    Text = "Работный дом: взгляд скорби"
  },
  Stage_66381_Desc = {
    Text = "Не беспокойтесь, Страх — это древнейший инстинкт живых существ.\nБоги не обижают даже муравья. Он дарует вам благословение через пробуждение."
  },
  Stage_66381_Name = {
    Text = "Музей восковых фигур·Пугающий взор"
  },
  Stage_66381_StageInitStateText = {
