  Stage_70092_Desc = {
    Text = "Зачаток — скрытая прелюдия.\nНовое зачатие еще не произошло, новое семя еще не сформировалось, чудо еще в зачатке."
  },
  Stage_70092_Name = {
    Text = "Зачаток·Бред безумие"
  },
