  Stage_70093_Desc = {
    Text = "Зачаток — скрытая прелюдия.\nНовое зачатие еще не произошло, новое семя еще не сформировалось, чудо еще в зачатке."
  },
  Stage_70093_Name = {
    Text = "Зачаток·Бред шесть"
  },
  Stage_70094_Desc = {
    Text = "Многозародышевое Размножение — это первобытная Алчность. \nОт единственной матери происходит зачатие максимального количества потомков, упорно расширяясь в засушливых землях."
  },
  Stage_70094_Name = {
    Text = "Многозародышевое Размножение — Бред безумие"
  },
  Stage_70094_StageInitStateText = {
