  Stage_70404_Name = {
    Text = "Шепот кошки·третий"
  },
  Stage_70405_Desc = {
    Text = "Злобная черная кошка коварно улыбнулась, ты опустил голову и увидел, что кошелёк был разорван в одном месте.\nВ шляпе кошки напротив промелькнула вспышка света от сердечника из серебра."
  },
  Stage_70405_Name = {
    Text = "Коварство кошки·часть третья"
  },
  Stage_70406_Desc = {
    Text = "Злобная черная кошка коварно улыбнулась, ты опустил голову и увидел, что кошелёк был разорван в одном месте.\nВ шляпе кошки напротив промелькнула вспышка света от сердечника из серебра."
