  Stage_79587_Name = {
    Text = "Погребальный мотылёк — третья"
  },
  Stage_79588_Desc = {
    Text = "Сейчас Начало, расскажи мне всё, что знаешь, открой свою память передо мной.\nСейчас Начало, подчинись мне во всём, отдай мне свою душу.\nЯ сформирую тебя, исходя из самых глубин памяти, настоящим тебя."
  },
  Stage_79588_Name = {
    Text = "Клиника памяти·2"
  },
  Stage_79589_Desc = {
    Text = "Сейчас Начало, расскажи мне всё, что знаешь, открой свою память передо мной.\nСейчас Начало, подчинись мне во всём, отдай мне свою душу.\nЯ сформирую тебя, исходя из самых глубин памяти, настоящим тебя."
  },
  Stage_79589_Name = {
    Text = "Клиника памяти·Третья часть"
  },
  Stage_7958_Desc = {
    Text = "Ты погружаешься в тишину ночи,\nне осталось ни одного сомнения или спора,\nкак будто у тебя есть вечные объятия,\nмы лежим в спокойной уверенности."
  },
  Stage_7958_Name = {
    Text = "Комната"
  },
  Stage_79590_Desc = {
    Text = "Сейчас Начало, расскажи мне всё, что знаешь, открой свою память передо мной.\nСейчас Начало, подчинись мне во всём, отдай мне свою душу.\nЯ сформирую тебя, исходя из самых глубин памяти, настоящим тебя."
  },
