    Text = "Время вторжения в сны·часть первая"
  },
  Stage_79607_Desc = {
    Text = "Следуя ритму раскачивающегося маятника, слушая приятное пение насекомых вокруг, расслабьте уставшие напряжённые нервы. Врач Клементин проведёт вас в мир сновидений.\nДобро пожаловать в храм души."
  },
  Stage_79607_Name = {
    Text = "Время вторжения в сны, Часть 3"
  },
  Stage_79608_Desc = {
    Text = "Следуя ритму раскачивающегося маятника, слушая приятное пение насекомых вокруг, расслабьте уставшие напряжённые нервы. Врач Клементин проведёт вас в мир сновидений.\nДобро пожаловать в храм души."
  },
  Stage_79608_Name = {
    Text = "Время вторжения в сны: II"
  },
  Stage_7960_Desc = {
    Text = "Какое счастливое забытье. Оно вернуло моего ангела ко мне."
  },
  Stage_7960_Name = {
    Text = "Тайное окно"
  },
  Stage_7961_Desc = {
    Text = "Дневник — это Фрагмент памяти.\nВ ходе расследования всегда обнаруживаются дневники."
  },
  Stage_7961_Name = {
    Text = "Осколки памяти"
  },
  Stage_7962_Desc = {
    Text = "Заснеженные просторы, где расцветает лилия."
  },
  Stage_7962_Name = {
    Text = "28 дней"
  },
  Stage_7963_Desc = {
    Text = "Когда знатные потеряют свою Независимый, когда богачи обанкротятся, они окажутся в безвыходном положении, как и ты сейчас."
  },
  Stage_7963_Name = {
    Text = "Пролететь над гнездом кукушки"
  },
  Stage_7964_Desc = {
    Text = "Это мир, созданный для неё, это великая любовь и ужасная клетка ."
  },
  Stage_7964_Name = {
    Text = "Психиатрическая больница"
  },
  Stage_7965_Desc = {
    Text = "Схватки в этом мире не ограничиваются лишь полем битвы с сталкивающимися клинками, иногда они происходят и в словах безумца."
  },
  Stage_7965_Name = {
    Text = "Рот сумасшедшего"
  },
  Stage_7966_Desc = {
    Text = "Тихо горящее пламя, шепчет путнику пустые обещания."
  },
  Stage_7966_Name = {
    Text = "Мотыльки на Искра"
  },
  Stage_7967_Desc = {
    Text = "Траектория, окутанная туманом, бесчисленные Шаги блуждают по ней, каждый след — это вопрос судьбе."
  },
  Stage_7967_Name = {
    Text = "Передняя дорога заблудилась"
  },
  Stage_7968_Desc = {
    Text = "Оно неустанно преследует тех, кто нарушает правила, захватчиков.\nЧто такое «Правила», и что такое «Нарушение»?\nСобака-охотник никогда не размышляет — это только помешает ее броску вперёд."
  },
  Stage_7968_Name = {
    Text = "Тень извне I"
  },
  Stage_7969_Desc = {
    Text = "Она приняла святые останки в своё тело, наставляла своих последователей в учении и распространяла веру своим ядовитым жалом."
  },
  Stage_7969_Name = {
    Text = "Хватка благочестия I"
  },
  Stage_7970_Desc = {
    Text = "Буря всё ещё набирает силу, но ещё не завершено."
  },
  Stage_7970_Name = {
    Text = "Перезапуск реальности"
  },
  Stage_7971_Desc = {
    Text = "Это вовсе не ожидаемая жизнь, а всего лишь омерзительный Паразит."
  },
  Stage_7971_Name = {
    Text = "Паразит"
  },
  Stage_7972_Desc = {
    Text = "Плыви к суше, плыви к надежде."
  },
  Stage_7972_Name = {
    Text = "Трагический старт"
  },
  Stage_7973_Desc = {
    Text = "Ночь поглощается тёмными потоками, звёзды теряют свой голос. Кризисный месяц, скрывающий перемены и бури, молча освещает неизвестно."
  },
  Stage_7973_Name = {
    Text = "Кризисный месяц"
  },
  Stage_7974_Desc = {
    Text = "Преследуя влекущий Погоня за светом во мраке бесконечной ночи, подобно Пепельной моль, стремящейся к пламени, я неудержимо лечу навстречу огням судьбы."
  },
  Stage_7974_Name = {
    Text = "Погребальный мотылёк"
  },
  Stage_7975_Desc = {
    Text = "Дружба, дрожавшая в прошлые времена, принесла новые надежды."
  },
  Stage_7975_Name = {
    Text = "Старые друзья и новые знакомые"
  },
  Stage_7976_Desc = {
    Text = "Трепетать и бороться в бурном ветре судьбы, но не упасть окончательно."
  },
  Stage_7976_Name = {
    Text = "Шаткий"
  },
  Stage_7977_Desc = {
    Text = "Навстречу ветру и песку, воин неумолимо бежит к солнцу."
  },
  Stage_7977_Name = {
    Text = "Солнечный поход"
  },
  Stage_7978_Desc = {
    Text = "Ползёт, течёт... опухоль протоплазмы ускользает через щели оков.\nЭто цена, которую она заплатила за «Свободу»."
  },
  Stage_7978_Name = {
    Text = "Цепь тьмы V"
  },
  Stage_7979_Desc = {
    Text = "Куча грубого, не переваренного вещества. Люди называют его экскрементами, или хаосом. \nМир родился из экскрементов."
  },
  Stage_7979_Name = {
    Text = "Кластер хаоса III"
  },
  Stage_7980_Desc = {
    Text = "Появившиеся непонятно откуда статуи блуждают в Мрак, вызывая дрожь.\nОни танцуют под древний ритм, следуя звуку флейты, доносящемуся Издалека."
  },
  Stage_7980_Name = {
    Text = "Путешествие в сверхизмерении·интервалVIII"
  },
  Stage_7981_Desc = {
    Text = "Они искажаются в тёмном, сливаются, затем их бережно сохраняют в образах.\nЭто запланированная заранее Воссоединение."
  },
  Stage_7981_Name = {
    Text = "Болото плоти·промежуток V"
  },
  Stage_7982_Desc = {
    Text = "Потом она исчезла, вернувшись в темноту.\nЛюди подняли головы, устремили взгляды вверх, наблюдая за небом, по которому она пролетела."
  },
  Stage_7982_Name = {Text = "Сосна"},
  Stage_7983_Desc = {
    Text = "Одна маленькая мышка, одна маленькая мышка.\nбегала, бегала, она отрезала хвост мышки мясным ножом."
  },
  Stage_7983_Name = {
    Text = "Браун, вперёд!"
  },
  Stage_7984_Desc = {
    Text = "Ты погружаешься в тишину ночи,\nне осталось ни одного сомнения или спора,\nкак будто у тебя есть вечные объятия,\nмы лежим в спокойной уверенности."
  },
  Stage_7984_Name = {
    Text = "Комната"
  },
  Stage_7985_Desc = {
    Text = "Лондиниум известен своей блестящей индустриальной цивилизацией, а также свинцово-серым густым туманом, окутывающим весь город.\nТуман присутствует повсюду и для прохожих представляет собой незначительное и случайное неудобство."
  },
  Stage_7985_Name = {
    Text = "Столица жутких туманов III"
  },
  Stage_7986_Desc = {
    Text = "На алтаре её красоты я готов принести в жертву свои слёзы, вздохи и моё преданное сердце."
  },
  Stage_7986_Name = {
    Text = "Галатея"
  },
  Stage_7987_Desc = {
    Text = "Бам-бам, треснул.\nбам-бам, сломался."
  },
  Stage_7987_Name = {
    Text = "Кукольный музей"
  },
  Stage_7988_Desc = {
    Text = "Правила, не для того ли они и существуют, чтобы их нарушать?"
  },
  Stage_7988_Name = {
    Text = "Три правила"
  },
  Stage_7989_Desc = {
    Text = "Прибрежный городок — Скарборо, расположенный в северном Йоркшире. Здесь есть высокие обрывы и золотистые бухты, что делает это место прекрасным курортом."
  },
  Stage_7989_Name = {
    Text = "Лето в Скарборо"
  },
  Stage_7990_Desc = {
    Text = "О, руки, надоедливые руки! Они постоянно дергают меня за волосы."
  },
  Stage_7990_Name = {
    Text = "Двадцать четыре"
  },
  Stage_7991_Desc = {
    Text = "Она почерпнула немало практического знания в психологии из слёз и экскрементов человека — больше, чем из всех книг."
  },
  Stage_7991_Name = {
    Text = "Руководство по диагностике и лечению"
  },
  Stage_7992_Desc = {
    Text = "Чтобы сохранить ваше здоровье, избегайте никотина."
  },
  Stage_7992_Name = {
    Text = "Дым и сирень"
  },
  Stage_7993_Desc = {
    Text = "Прибрежный городок — Скарборо, расположенный в северном Йоркшире. Здесь есть высокие обрывы и золотистые бухты, что делает это место прекрасным курортом."
  },
  Stage_7993_Name = {
    Text = "Лето в Скарборо"
  },
  Stage_7994_Desc = {
    Text = "Чтобы сохранить ваше здоровье, избегайте никотина."
  },
  Stage_7994_Name = {
    Text = "Дым и сирень"
  },
  Stage_7995_Desc = {
    Text = "Одна маленькая мышка, одна маленькая мышка.\nбегала, бегала, она отрезала хвост мышки мясным ножом."
  },
  Stage_7995_Name = {
    Text = "Браун, вперёд!"
  },
  Stage_7996_Desc = {
    Text = "Потом она исчезла, вернувшись в темноту.\nЛюди подняли головы, устремили взгляды вверх, наблюдая за небом, по которому она пролетела."
  },
  Stage_7996_Name = {Text = "Сосна"},
  Stage_7997_Desc = {
    Text = "На алтаре её красоты я готов принести в жертву свои слёзы, вздохи и моё преданное сердце."
  },
  Stage_7997_Name = {
    Text = "Галатея"
  },
  Stage_7998_Name = {
    Text = "[Пролог]"
  },
  Stage_7999_Desc = {
    Text = "О, руки, надоедливые руки! Они постоянно дергают меня за волосы."
  },
  Stage_7999_Name = {
    Text = "Двадцать четыре"
  },
  Stage_8000_Desc = {
    Text = "Да, да. Глаза — это тюрьма для души, а душа — оковы для тела ."
  },
  Stage_8000_Name = {
    Text = "Меланхолия анатомии"
  },
  Stage_8001_Desc = {
    Text = "Верно, милая. Плачь вволю, оформи свою боль, как шедевр."
  },
  Stage_8001_Name = {
    Text = "Девушка и слёзы"
  },
  Stage_8002_Desc = {
    Text = "«Рука» приподнимает Занавес опускается ночи и бесшумно входит в этот мир."
  },
  Stage_8002_Name = {
    Text = "Омут грёз I"
  },
  Stage_8003_Desc = {
    Text = "«Рука» приподнимает Занавес опускается ночи и бесшумно входит в этот мир."
  },
  Stage_8003_Name = {
    Text = "Омут грёз III"
  },
  Stage_8004_Desc = {
    Text = "«Рука» приподнимает Занавес опускается ночи и бесшумно входит в этот мир."
  },
  Stage_8004_Name = {
    Text = "Омут грёз II"
  },
  Stage_8005_Desc = {
    Text = "«Рука» приподнимает Занавес опускается ночи и бесшумно входит в этот мир."
  },
  Stage_8005_Name = {
    Text = "Омут грёз V"
  },
  Stage_8006_Desc = {
    Text = "«Рука» приподнимает Занавес опускается ночи и бесшумно входит в этот мир."
  },
  Stage_8006_Name = {
    Text = "Омут грёз IV"
  },
  Stage_8007_Desc = {
    Text = "«Рука» приподнимает Занавес опускается ночи и бесшумно входит в этот мир."
  },
  Stage_8007_Name = {
    Text = "Омут грёз VII"
  },
  Stage_8008_Desc = {
    Text = "«Рука» приподнимает Занавес опускается ночи и бесшумно входит в этот мир."
  },
  Stage_8008_Name = {
    Text = "Омут грёз VI"
  },
  Stage_8009_Desc = {
    Text = "Здесь спят руины древнего города.\nОни так же ленивы, как и их Носитель."
  },
  Stage_8009_Name = {
    Text = "Руины Понпеи I"
  },
  Stage_8010_Desc = {
    Text = "Мы будем встречаться снова и снова, в разных временных и пространственных размерностях"
  },
  Stage_8010_Name = {
    Text = "До новой встречи"
  },
  Stage_8011_Desc = {
    Text = "Тайный в глубинах космоса изогнутый горизонт. \nОн ведёт тебя от тьмы к другой тьме."
  },
  Stage_8011_Name = {
    Text = "Свазиево горло II"
  },
  Stage_8012_Desc = {
    Text = "Тайный в глубинах космоса изогнутый горизонт. \nОн ведёт тебя от тьмы к другой тьме."
  },
  Stage_8012_Name = {
    Text = "Свазиево горло V"
  },
  Stage_8013_Desc = {
    Text = "Никто и никогда не сможет снять венец, дарованный богом-королем."
  },
  Stage_8013_Name = {
    Text = "«Слава Лимурии»"
  },
  Stage_8014_Desc = {
    Text = "Дружба, дрожавшая в прошлые времена, принесла новые надежды."
  },
  Stage_8014_Name = {
    Text = "Старые друзья и новые знакомые"
  },
  Stage_8015_Desc = {
    Text = "Ночь поглощается тёмными потоками, звёзды теряют свой голос. Кризисный месяц, скрывающий перемены и бури, молча освещает неизвестно."
  },
  Stage_8015_Name = {
    Text = "Кризисный месяц"
  },
  Stage_8016_Desc = {
    Text = "Да, Алчность — это его первородный грех, и он будет испытывать Покаяние из-за этого."
  },
  Stage_8016_Name = {
    Text = "Аннигиляция"
  },
  Stage_8017_Desc = {
    Text = "Молчаливый хранитель издал новое звучание."
  },
  Stage_8017_Name = {
    Text = "Перегрузочная защита"
  },
  Stage_8018_Desc = {
    Text = "Преследуя влекущий Погоня за светом во мраке бесконечной ночи, подобно Пепельной моль, стремящейся к пламени, я неудержимо лечу навстречу огням судьбы."
  },
  Stage_8018_Name = {
    Text = "Погребальный мотылёк"
  },
  Stage_8019_Desc = {
    Text = "«Дверь» уже включена, Иллюзия скоро прояснится.\nШшш... не смотри, не слушай."
  },
  Stage_8019_Name = {
    Text = "Область Хаоса·Промежуток между сменами III"
  },
  Stage_8020_Desc = {
    Text = "«Дверь» уже включена, Иллюзия скоро прояснится.\nШшш... не смотри, не слушай."
  },
  Stage_8020_Name = {
    Text = "Область Хаоса·Промежуток между сменами III"
  },
  Stage_8021_Desc = {
    Text = "«Дверь» уже включена, Иллюзия скоро прояснится.\nШшш... не смотри, не слушай."
  },
  Stage_8021_Name = {
    Text = "Область Хаоса·Промежуток между сменами III"
  },
  Stage_8022_Desc = {
    Text = "Это вовсе не ожидаемая жизнь, а всего лишь омерзительный Паразит."
  },
  Stage_8022_Name = {
    Text = "Паразит"
  },
  Stage_8023_Desc = {
    Text = "Какое счастливое забытье. Оно вернуло моего ангела ко мне."
  },
  Stage_8023_Name = {
    Text = "Тайное окно"
  },
  Stage_80242_Desc = {
    Text = "В конце истории мир все еще горит, я уже готов к прощанию.\nНо мы все равно встретимся."
  },
  Stage_80242_Name = {
    Text = "Сожженный мир, до свидания"
  },
  Stage_80243_Desc = {
    Text = "Человек — социальное существо, они подвержены влиянию общества и сами влияют на него.\nИтак, скажи мне, каким человеком ты стал под воздействием жизни и окружающей среды?"
  },
  Stage_80243_Name = {
    Text = "Эксперимент по реконструкции познания"
  },
  Stage_80244_Desc = {
    Text = "Простите, у меня нет подарков для вас. \nЭтот маленький куколка — это мое самое глубокое благословение: в моменты отчаяния, пожалуйста, обязательно разорви кокон и возродись."
  },
  Stage_80244_Name = {
    Text = "Кукла дружбы"
  },
  Stage_80245_Desc = {
    Text = "Пламя приносит Погоня за светом, но также приносит боль и Урон.\nКогда весь мир горит, я готов преобразовать жизнь в каплю слезы, собравшуюся в Океан боли."
  },
  Stage_80245_Name = {
    Text = "Привет, горящий мир"
  },
  Stage_80246_Desc = {
    Text = "Герой одинок, человек не может по-настоящему понять его, дракон тоже не в силах постичь его. \nСражение с драконом или стать драконом — это вопрос."
  },
  Stage_80246_Name = {
    Text = "Одинокий храбрец"
  },
  Stage_80247_Desc = {
    Text = "Я полон мечт о мире, надеюсь, цветы всегда цветут, надеюсь, улыбки сохранятся навсегда.\nНо жизнь подарила мне всего лишь одну мечту."
  },
  Stage_80247_Name = {
    Text = "У меня много мечт"
  },
  Stage_80248_Desc = {
    Text = "Группа как текучий янтарь, каждая душа преломляет Погоня за светом других, но в прозрачной клетке видит только свое отражение."
  },
  Stage_80248_Name = {
    Text = "Социальное животное"
  },
  Stage_80249_Desc = {
    Text = "Я и мой Близкий Близкий друг, и мой враг.\nЭто сотрудничество и бой не прекратятся, пока на арене не останется один."
  },
  Stage_80249_Name = {
    Text = "Двойное тело"
  },
  Stage_8024_Desc = {
    Text = "Независимо, насколько тяжелым является металлическое тело, душа весит всего 21 грамм."
  },
  Stage_8024_Name = {
    Text = "21 грамм"
  },
  Stage_80250_Desc = {
    Text = "Маленькая Глава о бабочке, пролетая сквозь мечты, летит в реальность.\nВозможно, она слишком глупа, но выбор бабочки отличается от выбора человека."
  },
  Stage_80250_Name = {
    Text = "Бабочка летит"
  },
  Stage_80251_Desc = {
    Text = "Давайте посмотрим, какие ингредиенты и структура составляют «тебя» и «меня»."
  },
  Stage_80251_Name = {Text = "Глаза"},
  Stage_80252_Desc = {
    Text = "О, Близкий Близкий друг, мы все мечтаем.\nТолько одни делают мечты реальностью, а реальность некоторых, как довольно абсурдная мечта."
  },
  Stage_80252_Name = {
    Text = "Неконтролируемая мечта"
  },
  Stage_80253_Desc = {
    Text = "Я хочу танцевать в утраченной памяти, забыть о тех, кто любил меня и о ком я любил, и вечно танцевать только с собой, до самого конца времени."
  },
  Stage_80253_Name = {
    Text = "Утраченные воспоминания"
  },
  Stage_80254_Desc = {
    Text = "Беги, беги, щенок, беги.\nПродемонстрируй нам комедию своей паники и боли."
  },
  Stage_80254_Name = {
    Text = "Погоня"
  },
  Stage_80255_Desc = {
    Text = "Смотря на тебя, я смотрю на тебя.\nКаждую минуту, каждый мгновение, просто смотрю на тебя."
  },
  Stage_80255_Name = {
    Text = "Взгляды других"
  },
  Stage_80256_Desc = {
    Text = "Воспоминания ненадежны, потому что при поиске они начинают уничтожаться и выцветать. Как можно навсегда зафиксировать твой образ?\nЕсли воспоминания не прочные, то запечатлей их в жизни."
  },
  Stage_80256_Name = {
    Text = "Похожие тени"
  },
  Stage_80257_Desc = {
    Text = "Первые три выстрела — это просто прелюдия. \nПоследние два выстрела, один отнимает его жизнь, а другой — его душу."
  },
  Stage_80257_Name = {
    Text = "Пять выстрелов"
  },
  Stage_80258_Desc = {
    Text = "«Любопытство» задает тебе вопрос, зная, что Лечение полон терний, что сожжет тебя дотла, но ты не можешь отказать.\nТы в конечном итоге та же неотказная «кошка любопытства»."
  },
  Stage_80258_Name = {
    Text = "Любопытство убивает кошку"
  },
  Stage_80259_Desc = {
    Text = "Мир - это огромный санаторий, в котором каждый сходит с ума или скрывает своё Безумие.\nТак что, может, надо устроить психологическую консультацию?"
  },
  Stage_80259_Name = {
    Text = "Приглашение на консультацию"
  },
  Stage_8025_Desc = {
    Text = "Это мир, созданный для неё, это великая любовь и ужасная клетка ."
  },
  Stage_8025_Name = {
    Text = "Психиатрическая больница"
  },
  Stage_80260_Desc = {
    Text = "О, Близкий Близкий друг, мы все мечтаем.\nТолько одни делают мечты реальностью, а реальность некоторых, как довольно абсурдная мечта."
  },
  Stage_80260_Name = {
    Text = "Неконтролируемая мечта"
  },
  Stage_80261_Desc = {
    Text = "Я хочу танцевать в утраченной памяти, забыть о тех, кто любил меня и о ком я любил, и вечно танцевать только с собой, до самого конца времени."
  },
  Stage_80261_Name = {
    Text = "Утраченные воспоминания"
  },
  Stage_80262_Desc = {
    Text = "Беги, беги, щеночек, скорее беги.\nСвоими паническими и беспомощными усилиями, пусть они станут для нас комедией."
  },
  Stage_80262_Name = {
    Text = "Погоня"
  },
  Stage_80263_Desc = {
    Text = "Воспоминания ненадежны, потому что при поиске они начинают уничтожаться и выцветать. Как можно навсегда зафиксировать твой образ?\nЕсли воспоминания не прочные, то запечатлей их в жизни."
  },
  Stage_80263_Name = {
    Text = "Похожие тени"
  },
  Stage_80264_Desc = {
    Text = "Первые три выстрела — это просто прелюдия. \nПоследние два выстрела, один отнимает его жизнь, а другой — его душу."
  },
  Stage_80264_Name = {
    Text = "Пять выстрелов"
  },
  Stage_80265_Desc = {
    Text = "Мир - это огромный санаторий, в котором каждый сходит с ума или скрывает своё Безумие.\nТак что, может, надо устроить психологическую консультацию?"
  },
  Stage_80265_Name = {
    Text = "Приглашение на консультацию"
  },
  Stage_80266_Desc = {
    Text = "Пламя приносит Погоня за светом, но также приносит боль и Урон.\nКогда весь мир горит, я готов преобразовать жизнь в каплю слезы, собравшуюся в Океан боли."
  },
  Stage_80266_Name = {
    Text = "Привет, горящий мир"
  },
  Stage_80267_Desc = {
    Text = "Герой одинок, человек не может по-настоящему понять его, дракон тоже не в силах постичь его. \nСражение с драконом или стать драконом — это вопрос."
  },
  Stage_80267_Name = {
    Text = "Одинокий храбрец"
  },
  Stage_80268_Desc = {
    Text = "Человек — социальное существо, они подвержены влиянию общества и сами влияют на него.\nИтак, скажи мне, каким человеком ты стал под воздействием жизни и окружающей среды?"
  },
  Stage_80268_Name = {
    Text = "Эксперимент по реконструкции познания"
  },
  Stage_80269_Desc = {
    Text = "Я полон мечт о мире, надеюсь, цветы всегда цветут, надеюсь, улыбки сохранятся навсегда.\nНо жизнь подарила мне всего лишь одну мечту."
  },
  Stage_80269_Name = {
    Text = "У меня много мечт"
  },
  Stage_8026_Desc = {
    Text = "Когда знатные потеряют свою Независимый, когда богачи обанкротятся, они окажутся в безвыходном положении, как и ты сейчас."
  },
  Stage_8026_Name = {
    Text = "Пролететь над гнездом кукушки"
  },
  Stage_80270_Desc = {
    Text = "Я и мой Близкий Близкий друг, и мой враг.\nЭто сотрудничество и бой не прекратятся, пока на арене не останется один."
  },
  Stage_80270_Name = {
    Text = "Двойное тело"
  },
  Stage_80271_Desc = {
    Text = "Маленькая Глава о бабочке, пролетая сквозь мечты, летит в реальность.\nВозможно, она слишком глупа, но выбор бабочки отличается от выбора человека."
  },
  Stage_80271_Name = {
    Text = "Бабочка летит"
  },
  Stage_8027_Desc = {
    Text = "Схватки в этом мире не ограничиваются лишь полем битвы с сталкивающимися клинками, иногда они происходят и в словах безумца."
  },
  Stage_8027_Name = {
    Text = "Рот сумасшедшего"
  },
  Stage_8028_Desc = {
    Text = "Перерезав тонкие нити на марионетке, она больше никогда не будет танцевать."
  },
  Stage_8028_Name = {
    Text = "Ночь без птиц"
  },
  Stage_8029_Desc = {
    Text = "Не оглядывайся! Какое драгоценное предупреждение, не повторяй судьбу Орфея."
  },
  Stage_8029_Name = {
    Text = "Не оглядывайся"
  },
  Stage_8030_Desc = {
    Text = "Кто способен истолковать значение «Весны»?\nСмерть и забвение, таящиеся в безмолвной пустоте, растворяются в туманном весеннем мареве."
  },
  Stage_8030_Name = {
    Text = "Весна Боттичелли"
  },
  Stage_8031_Desc = {
    Text = "Дневник — это Фрагмент памяти.\nВ ходе расследования всегда обнаруживаются дневники."
  },
  Stage_8031_Name = {
    Text = "Осколки памяти"
  },
  Stage_8032_Desc = {
    Text = "Первое знакомство, мой Носитель."
  },
  Stage_8032_Name = {
    Text = "Шестое чувство"
  },
  Stage_8033_Desc = {
    Text = "Они искажаются в тёмном, сливаются, затем их бережно сохраняют в образах.\nЭто запланированная заранее Воссоединение."
  },
  Stage_8033_Name = {
    Text = "Болото плоти·интервалVI"
  },
  Stage_8034_Desc = {
    Text = "Ещё до рождения звёзд, они уже существовали здесь.\nОни были и пустотой, и всем сразу."
  },
  Stage_8034_Name = {
    Text = "Мутное последнее изображение III"
  },
  Stage_8035_Desc = {
    Text = "Случайное 4"
  },
  Stage_8035_Name = {
    Text = "Зеркало Лунного Болота IV"
  },
  Stage_8036_Desc = {
    Text = "Случайное 5"
  },
  Stage_8036_Name = {
    Text = "Зеркало Лунного Болота V"
  },
  Stage_8037_Desc = {
    Text = "«Дверь» вот-вот включится, и ты увидишь часть истины.\nНе черная, не белая — истина цветная и мутная."
  },
  Stage_8037_Name = {
    Text = "Область Хаоса·Промежуток между сменамиI"
  },
  Stage_8038_Desc = {
    Text = "Случайный 1"
  },
  Stage_8038_Name = {
    Text = "Зеркало Лунного Болота I"
  },
  Stage_8039_Desc = {
    Text = "«Дверь» вот-вот включится, и ты увидишь часть истины.\nНе черная, не белая — истина цветная и мутная."
  },
  Stage_8039_Name = {
    Text = "Область Хаоса·Промежуток между сменамиI"
  },
  Stage_8040_Desc = {
    Text = "«Дверь» вот-вот включится, и ты увидишь часть истины.\nНе черная, не белая — истина цветная и мутная."
  },
  Stage_8040_Name = {
    Text = "Область Хаоса·Промежуток между сменамиI"
  },
  Stage_8041_Desc = {
    Text = "Рамона вернулась в команду. Путешествие следователя Мисаг продолжить."
  },
  Stage_8041_Name = {
    Text = "Вчера повторилось"
  },
  Stage_8042_Desc = {
    Text = "Под заброшенным железнодорожным мостом огромный и громоздкий монстр издает низкий рык. Чтобы добраться до лечебницы Лай, нужно пересечь это место."
  },
  Stage_8042_Name = {
    Text = "Лодка доедет до моста, и всё наладится само собой"
  },
  Stage_8043_Desc = {
    Text = "Всё, что ты хочешь знать, перед твоими глазами, просто ты никогда этого не обнаружил."
  },
  Stage_8043_Name = {
    Text = "Под сенью"
  },
  Stage_8044_Desc = {
    Text = "Жизнь похожа на спираль, кошмары, от которых когда-то удалось Побег, всегда возвращаются в полночь."
  },
  Stage_8044_Name = {
    Text = "Вернуться к началу"
  },
  Stage_8045_Desc = {
    Text = "В шёпоте Рамона и Ротань, Страж погружается в сновидение в клетке."
  },
  Stage_8045_Name = {
    Text = "Не надо исправлять то, что не сломано"
  },
  Stage_8046_Desc = {
    Text = "Бог сказал, что они должны родиться, чтобы претерпеть страдания и пролить кровь.\nТак же, как солнце должно восходить, а дождь должен падать.\nВсё происходит к лучшему."
  },
  Stage_8046_Name = {
    Text = "Земля Горьких Дождей"
  },
  Stage_8047_Desc = {
    Text = "Музей восковых фигур Роджерса находится в самом дальнем конце улицы Саутуорк, недалеко от притока реки Темза.\nОн не выделяется, но привлекает множество поклонников авангардного искусства."
  },
  Stage_8047_Name = {
    Text = "Маниакальный восковой музей II"
  },
  Stage_8048_Desc = {
    Text = "Оно единственное живое существо здесь, и всё, что оно видит, подчиняется ему.\n—— Оно является верховным королём."
  },
  Stage_8048_Name = {
    Text = "Королевство зверей"
  },
  Stage_8049_Desc = {
    Text = "Его царство - это космическая оболочка, Его желание безгранично и необъятно."
  },
  Stage_8049_Name = {
    Text = "Червоточина I"
  },
  Stage_8050_Desc = {
    Text = "«Рука» приподнимает Занавес опускается ночи и бесшумно входит в этот мир."
  },
  Stage_8050_Name = {
    Text = "Омут грёз V"
  },
  Stage_8051_Desc = {
    Text = "Обрушенный идол смотрит на своих подданных.\nНаблюдает, как они выживают, плодятся, сражаются, а затем полностью забывают о нем.\nОбрушенный идол тоскует по своим подданным."
  },
  Stage_8051_Name = {
    Text = "Омут грёз II"
  },
  Stage_8052_Desc = {
    Text = "Обрушенный идол смотрит на своих подданных.\nНаблюдает, как они выживают, плодятся, сражаются, а затем полностью забывают о нем.\nОбрушенный идол тоскует по своим подданным."
  },
  Stage_8052_Name = {
    Text = "Омут грёз III"
  },
  Stage_8053_Desc = {
    Text = "Это фильм без конца, она спит в антракте уже много лет.\nОна видит розы летнего полдня, а также Пепел и ветер.."
  },
  Stage_8053_Name = {
    Text = "Поэтическое общество Фелин"
  },
  Stage_8054_Desc = {
    Text = "Обрушенный идол смотрит на своих подданных.\nНаблюдает, как они выживают, плодятся, сражаются, а затем полностью забывают о нем.\nОбрушенный идол тоскует по своим подданным."
  },
  Stage_8054_Name = {
    Text = "Омут грёз VI"
  },
  Stage_8055_Desc = {
    Text = "Обрушенный идол смотрит на своих подданных.\nНаблюдает, как они выживают, плодятся, сражаются, а затем полностью забывают о нем.\nОбрушенный идол тоскует по своим подданным."
  },
  Stage_8055_Name = {
    Text = "Омут грёз VII"
  },
  Stage_8056_Desc = {
