  Stage_81202_Name = {
    Text = "Руководство навигатора·часть пятая"
  },
  Stage_81203_Desc = {
    Text = "Восхваляйте, безумствуйте, угождайте великому @3 с вашей болью и смертью."
  },
  Stage_81203_Name = {
    Text = "Ритуал Жертвоприношения"
  },
  Stage_81204_Desc = {
    Text = "О, молодой навигатор, ты в конечном итоге будешь обняты соленой водой и станешь путеводным светом."
  },
  Stage_81204_Name = {
    Text = "Песня навигатора"
  },
  Stage_81205_Desc = {
    Text = "Перед приходом темноты не было света, а лишь менее темной тьмы.\nПоскольку всегда найдется кто-то, кто поднимет факел."
  },
  Stage_81205_Name = {
    Text = "Перед наступлением темноты"
  },
  Stage_81206_Desc = {
    Text = "Звёздный диск — глаза морехода, он помогает нам находить направление на ночном небе."
  },
  Stage_81206_Name = {
    Text = "Пятнистый звездный диск·третья"
  },
  Stage_81207_Desc = {
    Text = "Пока судно на плаву, я буду выполнять свои лоцманские обязанности.\nТак было всегда, и так будет всегда."
  },
  Stage_81207_Name = {
    Text = "Будущие морские пути"
  },
  Stage_81208_Desc = {
    Text = "Звёздный диск — глаза морехода, он помогает нам находить направление на ночном небе."
  },
  Stage_81208_Name = {
    Text = "Пятнистый звездный диск·четвертая"
  },
  Stage_81209_Desc = {
    Text = "Эта старая морская Карта забита мелким шрифтом, полна всех событий всех владельцев с момента её создания."
  },
  Stage_81209_Name = {
    Text = "Старинная Карта · Шесть"
  },
  Stage_8120_Desc = {
    Text = "Опасность исходит изнутри."
  },
  Stage_8120_Name = {
    Text = "Внутренний риск"
  },
  Stage_81210_Desc = {
    Text = "Эта старая морская Карта забита мелким шрифтом, полна всех событий всех владельцев с момента её создания."
  },
  Stage_81210_Name = {
    Text = "Старинная Карта · Безумие"
  },
  Stage_81211_Desc = {
    Text = "Метким использованием оптических инструментов людям удалось заглянуть в углы звезд."
  },
  Stage_81211_Name = {
    Text = "Старинный Секстант·часть первая"
  },
  Stage_81212_Desc = {
    Text = "Секстант сверкает, карты либо разворачиваются, мы расшифровываем тайнопись Южного Креста, измеряем тайны океанов...\nДаже если я распадусь, я не пожалею о своем выборе, зная, что с того момента, как я стал лоцманом, моя Колесо Судьбы была решена."
