  Stage_83250_Name = {
    Text = "Зона Р-эффекта·Волна 4·Обычный"
  },
  Stage_88880_Desc = {
    Text = "Я несу Искра, который ты когда-то зажег.\nТы направлял меня, теперь я стану твоими глазами и верну тебе Погоня за светом.\nТвой путь пройду я за тебя, и вся заржавевшая ограда рухнет перед этим огнем."
  },
  Stage_88880_Name = {
    Text = "Переносчик свечей·Третий"
  },
  Stage_88881_Desc = {
    Text = "Замороженный город, застывший в образе цивилизации."
  },
  Stage_88881_Name = {
    Text = "Экспонат"
  },
  Stage_88882_Desc = {
    Text = "Он родился глупым, неуклюжим, зажатым в простой жизни, слепым и упрямым.\nНо кто сказал, что дурак не может найти совершенно новый путь? Все преграды — всего лишь нераскрывшийся шторм; даже если он абсолютно ничего не знает, он все равно смело полетит в незнаемое небо."
  },
  Stage_88882_Name = {
    Text = "Дурак: безумие"
  },
  Stage_88883_Desc = {
    Text = "Мне приснились далекие старые дни.\nВ те времена ты указывал на звезды в книгах, которые выглядели как глубокие звезды, рассыпанные на синем бархате, говоря, что в один из ясных вечеров мы должны полететь рядом с луной, чтобы взглянуть, какие виды скрываются над небом."
  },
  Stage_88883_Name = {
    Text = "Сон вчерашнего дня·шестая"
  },
  Stage_88884_Desc = {
    Text = "У него всегда были две тени, но сейчас он потерял одну.\nОн одиноко шел под тихим ночным небом и пел песню, которую вместе с ним составила его Детство.\nПтицы, птицы, где же вы......\nТени, тени, возвращайтесь домой……"
  },
  Stage_88884_Name = {
    Text = "Одинокое путешествие·часть пятая"
  },
  Stage_88885_Desc = {
    Text = "Я несу Искра, который ты когда-то зажег.\nТы направлял меня, теперь я стану твоими глазами и верну тебе Погоня за светом.\nТвой путь пройду я за тебя, и вся заржавевшая ограда рухнет перед этим огнем."
  },
  Stage_88885_Name = {
    Text = "Переносчик свечей·Четвертый"
  },
  Stage_88886_Desc = {
    Text = "Я несу Искра, который ты когда-то зажег.\nТы направлял меня, теперь я стану твоими глазами и верну тебе Погоня за светом.\nТвой путь пройду я за тебя, и вся заржавевшая ограда рухнет перед этим огнем."
  },
  Stage_88886_Name = {
    Text = "Переносчик свечей·Второй"
  },
  Stage_88887_Desc = {
    Text = "Если рожден в клетке, разве он должен быть приручен?  \nЕсли скрыт под землёй, он всё равно выберется на поверхность."
  },
  Stage_88887_Name = {
    Text = "Разгромить клетку·Партия пятая"
  },
  Stage_88888_Desc = {
    Text = "Если рожден в клетке, разве он должен быть приручен?  \nЕсли скрыт под землёй, он всё равно выберется на поверхность."
  },
  Stage_88888_Name = {
    Text = "Разгромить клетку·Партия шестая"
  },
  Stage_88889_Desc = {
