  Stage_90691_Name = {
    Text = "Лунный Погоня за светом, скелеты и танец"
  },
  Stage_90985_Desc = {
    Text = "Все преграды будут бояться и ползти, вся слава вернется в Рим.\nТот белоснежный венок и лавровый лист будут возложены на голову самого храброго воина."
  },
  Stage_90985_Name = {
    Text = "Корона воина·Часть 5"
  },
  Stage_90986_Desc = {
    Text = "Возгласы и цветы, Прекрасное Прекрасное вино и пиршество, золото и сокровища.\nСтремитесь, смейтесь, это слава, которую заслуживают воины!"
  },
  Stage_90986_Name = {
    Text = "Торжество о славе · часть пятая"
  },
  Stage_90987_Desc = {
    Text = "Все преграды будут бояться и ползти, вся слава вернется в Рим.\nТот белоснежный венок и лавровый лист будут возложены на голову самого храброго воина."
  },
  Stage_90987_Name = {
    Text = "Корона воина·два"
  },
  Stage_90988_Desc = {
    Text = "Где бы ни пряталась добыча, профессиональный охотник обязательно учует этот сладкий аромат."
  },
  Stage_90988_Name = {
    Text = "Дикий охотник·безумие"
  },
  Stage_90989_Desc = {
    Text = "Звук фанфар завоевания раздался, и воины уже начали свой путь.\nМы движемся вперед, мы неудержимы, мы непременно победим."
  },
  Stage_90989_Name = {
    Text = "Коготь похода·Часть 2"
  },
  Stage_90990_Desc = {
    Text = "Звук фанфар завоевания раздался, и воины уже начали свой путь.\nМы движемся вперед, мы неудержимы, мы непременно победим."
  },
  Stage_90990_Name = {
    Text = "Коготь похода·Часть 4"
  },
  Stage_90991_Desc = {
    Text = "Я признаю, у нас были некоторые недопонимания в прошлом, но это не мешает нам временно объединиться и направить свой Негодование на эту отвратительную, ненавистную, подлую современную технологию."
  },
  Stage_90991_Name = {
    Text = "Совместная мудрость·Часть 5"
  },
