  Stage_97663_Name = {
    Text = "Третий день · Один"
  },
  Stage_97807_Desc = {
    Text = "Мамочка - это заклинание, которое шепчат люди от рождения до смерти.\nНи один ребёнок не хочет взрослеть, ни один ребёнок не желает быть вне любящих объятий матери.\nТы должен сыграть жестокую судьбу и снова оторвать её из объятий матери?"
  },
  Stage_97807_Name = {
    Text = "Безупречная сказка·безумие"
  },
  Stage_97808_Desc = {
    Text = "Прекрасные слова часто рождаются из страдания.\nОна осознала эту красоту, когда уже знала о трагедии, скрытой в тенях жизни, которая уже пришла.\nО, красота — это всё, что мимолетно и разрушительно."
  },
  Stage_97808_Name = {
    Text = "Поэтический сад · шестая часть"
  },
  Stage_97809_Desc = {
    Text = "Если бы этот момент радости можно было заморозить, я бы хотел, чтобы память о нём длилась вечно."
  },
  Stage_97809_Name = {
    Text = "Одно фото"
  },
  Stage_97810_Desc = {
    Text = "Прекрасные слова часто рождаются из страдания.\nОна осознала эту красоту, когда уже знала о трагедии, скрытой в тенях жизни, которая уже пришла.\nО, красота — это всё, что мимолетно и разрушительно."
  },
  Stage_97810_Name = {
    Text = "Поэтический сад · вторая часть"
  },
  Stage_97811_Desc = {
    Text = "Она не забывала свои мечты, даже потеряв душу.\nЧеловек, погибший из-за науки, когда-то горячо жил ради науки."
  },
  Stage_97811_Name = {
    Text = "Механический сон: безумие"
  },
  Stage_97812_Desc = {
    Text = "Ты прогуливался по знакомому, но в то же время чужому кампусу, смотря на всё вокруг, шумное, но обычное, ты дал бы этому радоваться или печалиться, что ничего из этого никогда не имел?"
  },
  Stage_97812_Name = {
    Text = "Вернуться на прежние места·Часть пятая"
  },
