  Stage_98829_Name = {
    Text = "Безмолвное пробуждение·Часть 3"
  },
  Stage_98830_Desc = {
    Text = "Согласно легенде, судьбы близнецов предначертаны навсегда быть связанными, неотрывными.\nПод безбрежным небом, подарившим жизнь бесчисленному количеству существ, мы наконец встретимся вновь."
  },
  Stage_98830_Name = {
    Text = "Двойные крылья: вторая"
