  Stage_99725_Desc = {
    Text = "Критика — это не обязанность художника; создание — вот что важно."
  },
  Stage_99725_Name = {
    Text = "Салон на иле"
  },
  Stage_99726_Desc = {
    Text = "Мы всегда были заперты на одной и той же весах в противостоянии Близкий Близкий друг другу, но, дорогой брат, даже если мы не можем разрушить это, мы можем выбрать прыгнуть с этих весов."
  },
  Stage_99726_Name = {
    Text = "Перевернутые весы"
  },
  Stage_99727_Desc = {
    Text = "Пара взаимно прижимающихся птиц, суждено лишь петь в клетке."
  },
  Stage_99727_Name = {
    Text = "Двойная птица"
  },
  Stage_99728_Desc = {
    Text = "Как должен терпеть тот, кто видит реальность, это иллюзию?"
  },
  Stage_99728_Name = {
    Text = "Смотри, луна"
  },
  Stage_99729_Desc = {
    Text = "У судьбы самые плохие часы, она всегда заставляет утрату приходить слишком рано, а обладание — слишком поздно."
  },
  Stage_99729_Name = {
    Text = "Судьба в беспорядке"
  },
  Stage_99730_Desc = {
    Text = "Лети, лети, стремящаяся к свободе птица.\nНежный ветер уже поднимает тебя, проходя сквозь ливни и громы, эти черные крылья в конечном итоге отразят алая утренняя заря."
  },
  Stage_99730_Name = {
    Text = "Чисто-черные крылья"
  },
  Stage_99731_Desc = {
    Text = "Они танцуют, сливаются, поедают Близкий Близкий друг друга.\nОни делают все, что могут делать высокоразвитые существа."
  },
  Stage_99731_Name = {
    Text = "Старшие животные"
  },
  Stage_99732_Desc = {
    Text = "Как только ты вырвешь крылья у птицы, она постепенно забудет, как летать."
  },
  Stage_99732_Name = {
    Text = "За узкой дверью"
  },
  Stage_99733_Desc = {
    Text = "Зажги этот чёрный фитиль, посвятив всё Ему; пусть эта лампа светит вечно, очищая все грехи мира."
  },
  Stage_99733_Name = {
    Text = "Подношение"
  }
